<?php require __DIR__.'/app/bootstrap.php';$token=(string)($_GET['token']??'');$order=preg_match('/^[a-f0-9]{64}$/',$token)?query('SELECT * FROM orders WHERE access_token=?',[$token])->fetch():false;if(!$order){http_response_code(404);render_header('Order not found');echo '<main class="page"><h1>Order not found.</h1></main>';render_footer();exit;}$lines=query('SELECT * FROM order_items WHERE order_id=?',[$order['id']])->fetchAll();render_header('Order '.$order['reference']);?>
<main class="page narrow"><p class="eyebrow">THANK YOU FOR CHOOSING FLAWED</p><h1>Your order.<br><em>Your story.</em></h1><p class="notice">Order request received. Status: <strong><?=h(ucfirst($order['status']))?></strong></p><h2><?=h($order['reference'])?></h2><p>Save this private page to check your order status. Anyone with this link can view this order summary, so keep it private.</p><div class="summary-box"><?php foreach($lines as $line):?><div class="summary-line"><span><?=h($line['product_name'])?> / <?=h($line['size'])?> × <?=h($line['quantity'])?></span><strong><?=money($line['unit_price']*$line['quantity'])?></strong></div><?php endforeach ?><div class="summary-line"><span>Delivery</span><strong><?=$order['delivery_fee']===null?'To be confirmed':money($order['delivery_fee'])?></strong></div><div class="summary-line total"><span><?=$order['total']===null?'Product subtotal':'Total'?></span><strong><?=money($order['total']??$order['subtotal'])?></strong></div><p>Cash on delivery · <?=h($order['payment_status'])?></p><p>The team will contact you to confirm availability and delivery before dispatch. If you provided an email, an order acknowledgment will be sent when the store’s email connection is active. Keep this page as your order record.</p></div><a class="button dark" href="<?=url('index.php#shop')?>">CONTINUE EXPLORING ↗</a></main><?php render_footer(); ?>
